// Zentrale Seiten-Registrierung fuer alle ALLRIS-Web-Seiten (Dashboard/Formulare).
// Neue Seite hinzufuegen = hier ein Eintrag mehr, alle bestehenden Seiten zeigen
// den Link automatisch (jede Seite ruft diesen Sub-Workflow bei jedem Aufruf auf).
const PAGES = [
  { key: 'status', label: 'Status-Uebersicht', path: '/webhook/allris-status' },
  { key: 'wahlkampf', label: 'Wahlkampf-Bildgenerator', path: '/webhook/wahlkampf-bild' }
];

const THEMES = {
  dark: { barBg: '#181c24', barBorder: '#2a2d34', label: '#6a7079', pillBg: '#5b8def', pillFg: '#0f1115', pillHoverBg: '#7ba3f5', activeBg: '#2a2d34', activeFg: '#9aa0a6' },
  light: { barBg: '#eaeaea', barBorder: '#d0d0d0', label: '#777777', pillBg: '#333333', pillFg: '#ffffff', pillHoverBg: '#555555', activeBg: '#ffffff', activeFg: '#333333' }
};

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

return $input.all().map(item => {
  const currentPage = item.json.currentPage;
  const theme = THEMES[item.json.theme] || THEMES.light;
  const items = PAGES.map(p => {
    if (p.key === currentPage) return '<span class="allris-nav-pill allris-nav-active">' + esc(p.label) + '</span>';
    return '<a class="allris-nav-pill" href="' + esc(p.path) + '">' + esc(p.label) + '</a>';
  }).join('');
  const navHtml = '<nav class="allris-nav"><span class="allris-nav-label">Seiten</span>' + items + '</nav>';
  const navCss = '.allris-nav{display:flex;align-items:center;flex-wrap:wrap;gap:8px;background:' + theme.barBg + ';border:1px solid ' + theme.barBorder + ';padding:10px 16px;border-radius:8px;margin-bottom:20px;}' +
    '.allris-nav-label{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:' + theme.label + ';margin-right:4px;}' +
    '.allris-nav-pill{display:inline-block;padding:6px 14px;border-radius:6px;font-size:13px;font-weight:600;text-decoration:none;}' +
    'a.allris-nav-pill{background:' + theme.pillBg + ';color:' + theme.pillFg + ';}' +
    'a.allris-nav-pill:hover{background:' + theme.pillHoverBg + ';}' +
    '.allris-nav-active{background:' + theme.activeBg + ';color:' + theme.activeFg + ';cursor:default;}';
  return { json: { navHtml: navHtml, navCss: navCss } };
});
